function switchTab(id){activeTab=id;document.querySelectorAll('[data-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.tab===id);b.setAttribute('aria-selected',b.dataset.tab===id);b.tabIndex=b.dataset.tab===id?0:-1});if(id==='layers')renderLayers();else if(id==='community')renderCommunity();else renderEvidence();$('#sidebar-content').scrollTop=0}
