function openNote(latlng){cancelPlacement();let chosen=[latlng.lat,latlng.lng];openModal(`<div class="eyebrow">${t('WORKSHOP NOTE','UNA PERSPECTIVA EN SU LUGAR')}</div><h2>${t('Add a workshop note','Añadir una nota del taller')}</h2><p>${t('Record a question, concern or local insight. Save it on this device, then export it with the workshop notes.','Registra una pregunta, preocupación o conocimiento local. Guárdalo en este dispositivo y expórtalo con las notas del taller.')}</p><form id="note-form"><div class="form-grid"><div class="field"><label for="note-type">${t('Type','Tipo')}</label><select id="note-type">${Object.entries(noteTypes).map(([k,v])=>`<option value="${k}">${t(...v)}</option>`).join('')}</select></div><div class="field"><label for="note-topic">${t('Topic','Tema')}</label><select id="note-topic">${Object.entries(themes).filter(([k])=>k!=='all').map(([k,v])=>`<option value="${k}">${t(...v)}</option>`).join('')}</select></div></div><div class="field"><label for="note-text">${t('Note','¿Qué importa aquí?')}</label><textarea id="note-text" required minlength="5" maxlength="2000" placeholder="${t('Write your note…','Usa tus propias palabras. Evita nombres y datos personales.')}"></textarea></div><div class="field"><label for="note-precision">${t('Location precision','Precisión de ubicación')}</label><select id="note-precision"><option value="approx">${t('Area (~1 km)','Zona aproximada (~1 km)')}</option><option value="exact">${t('Selected point','Punto seleccionado exacto')}</option></select></div><div class="location-chip" id="note-location"></div><div class="form-actions"><button type="button" class="button" id="edit-location">${t('Choose another place','Elegir otro lugar')}</button><button type="submit" class="button dark">${t('Save on this device','Guardar en este dispositivo')}</button></div></form>`);const updateCoords=()=>{$('#note-location').textContent=(lang==='es'?'Ubicación: ':'Location: ')+chosen.map(v=>v.toFixed($('#note-precision').value==='exact'?5:2)).join(', ')+' · WGS84'};updateCoords();$('#note-precision').onchange=updateCoords;$('#edit-location').onclick=startPlacement;$('#note-form').onsubmit=e=>{e.preventDefault();const text=$('#note-text').value.trim();if(text.length<5){$('#note-text').setCustomValidity(t('Please add at least 5 characters.','Añade al menos 5 caracteres.'));$('#note-text').reportValidity();return}if(notes.length>=500){toast(t('Export your notes; the 500-note device limit has been reached.','Exporta las notas; se alcanzó el límite de 500 notas.'));return}const precision=$('#note-precision').value;const note={id:'note-'+crypto.randomUUID(),text,coords:chosen.map(v=>+v.toFixed(precision==='exact'?5:2)),type:$('#note-type').value,theme:$('#note-topic').value,precision,createdAt:new Date().toISOString(),language:lang,source:'Local workshop note',verification:'Unverified'};const next=[...notes,note];try{localStorage.setItem('minescope-notes-v1',JSON.stringify(next))}catch{toast(t('This browser could not save the note. Enable local storage and try again.','Este navegador no pudo guardar la nota. Habilita el almacenamiento local e inténtalo de nuevo.'));return}notes=next;drawNotes();themeFilter='all';filterCommunityMap();setLayer('community',true);communityView='notes';switchTab('community');$('#modal').close();showNote(note);toast(t('Workshop note saved on this device.','Nota guardada en este dispositivo.'))};$('#note-text').oninput=()=>$('#note-text').setCustomValidity('')}
function showNote(n){setInspector(`<div class="inspector-head">${closeButton()}<div class="eyebrow">${t('LOCAL WORKSHOP NOTE','NOTA LOCAL DEL TALLER')}</div><h2>${t(...noteTypes[n.type])}</h2><p class="inspector-sub">${t(...themes[n.theme])}</p></div><div class="inspector-body"><p class="user-note">${esc(n.text)}</p><span class="badge purple">${t(n.precision==='exact'?'Selected location':'Area location',n.precision==='exact'?'Punto seleccionado · sin verificar':'Zona aproximada · sin verificar')}</span><div class="card-divider"></div><div class="source-note">${n.coords.map(v=>v.toFixed(n.precision==='exact'?5:2)).join(', ')} · WGS84<br>${t('Saved on this device.','Guardada solo en este dispositivo. Se conserva el idioma original.')}</div><button class="button" id="show-notes">${t('View workshop notes','Ver notas del taller')} ↗</button></div>`,n.id);$('#show-notes').onclick=()=>{communityView='notes';switchTab('community')}}
function exportNotes(){const data={type:'FeatureCollection',name:'MineScope Dominga workshop notes',properties:{exportedAt:new Date().toISOString(),description:'Device-local, unverified workshop notes; not a representative survey. Approximate coordinates are rounded to 0.01 degrees.'},features:notes.map(n=>({type:'Feature',id:n.id,geometry:{type:'Point',coordinates:[n.coords[1],n.coords[0]]},properties:{text:n.text,topic:n.theme,type:n.type,precision:n.precision,createdAt:n.createdAt,language:n.language,source:n.source,verification:n.verification}}))};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/geo+json'}));const a=document.createElement('a');a.href=url;a.download='minescope-dominga-workshop.geojson';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(t('Workshop notes exported as GeoJSON.','Notas exportadas en GeoJSON.'))}
