document.querySelectorAll('[data-tab]').forEach((b,i)=>{b.onclick=()=>switchTab(b.dataset.tab);b.onkeydown=e=>{const tabs=[...document.querySelectorAll('[data-tab]')];let next;if(e.key==='ArrowRight')next=(i+1)%3;if(e.key==='ArrowLeft')next=(i+2)%3;if(e.key==='Home')next=0;if(e.key==='End')next=2;if(next!==undefined){e.preventDefault();switchTab(tabs[next].dataset.tab);tabs[next].focus()}}});
$('#reset-view').onclick=()=>{map.flyTo([-29.40,-71.24],10);showOverview()};$('#mobile-toggle').onclick=()=>setSidebar(true);$('#sidebar-close').onclick=()=>setSidebar(false);$('#sidebar-scrim').onclick=()=>setSidebar(false);map.on('mousemove',e=>$('#coordinates').innerHTML=`${Math.abs(e.latlng.lat).toFixed(3)}° ${e.latlng.lat<0?'S':'N'}&nbsp;&nbsp; ${Math.abs(e.latlng.lng).toFixed(3)}° ${e.latlng.lng<0?'W':'E'}`);map.on('click',e=>{if(placing)openNote(e.latlng);else if(mobileQuery.matches)$('#sidebar').classList.remove('open')});$('#add-note').onclick=startPlacement;$('#cancel-note').onclick=cancelPlacement;$('#center-note').onclick=()=>openNote(map.getCenter());document.addEventListener('keydown',e=>{if(e.key==='Escape'){cancelPlacement();$('#sidebar').classList.remove('open')}});$('.modal-close').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close()}});
layers.forEach(l=>setLayer(l.id,l.on));switchTab('layers');showOverview();$('#add-note').setAttribute('aria-label','Add note');
const mobileQuery=matchMedia('(max-width:700px), (orientation:portrait)');
function setSidebar(open){
  $('#sidebar').classList.toggle('open',open);syncSidebar();
  if(mobileQuery.matches)(open?$('#sidebar-close'):$('#mobile-toggle')).focus();
}
function syncSidebar(){
  const drawer=mobileQuery.matches,open=$('#sidebar').classList.contains('open');
  $('#sidebar').inert=drawer&&!open;
  $('#sidebar-scrim').hidden=!(drawer&&open);
  $('.map-shell').inert=drawer&&open;
  $('#mobile-toggle').setAttribute('aria-expanded',String(drawer?open:true));
  if(drawer&&!open&&$('#sidebar').contains(document.activeElement))$('#mobile-toggle').focus();
}
new MutationObserver(syncSidebar).observe($('#sidebar'),{attributes:true,attributeFilter:['class']});
mobileQuery.addEventListener('change',()=>{$('#sidebar').classList.remove('open');syncSidebar();map.invalidateSize({pan:false})});
document.addEventListener('keydown',e=>{
  if(e.key==='Tab'&&mobileQuery.matches&&$('#sidebar').classList.contains('open')&&!$('#modal').open){
    const focusable=[...$('#sidebar').querySelectorAll('button:not([disabled]),a[href],input,select,summary,[tabindex="0"]')].filter(el=>el.tabIndex>=0&&el.getClientRects().length);
    const first=focusable[0],last=focusable.at(-1);
    if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}
    else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}
  }
});
syncSidebar();if(mobileQuery.matches){$('#inspector').hidden=true;selected=null;}

